entries[311389] = { ["name"] = "Wahnsinn: Entomophobie", ["text"] = "Sofort\nWährend eines Kampfes krabbeln Kreaturen auf Euch herum. Bei 5 Kreaturen müsst Ihr einfach losrennen, um sie abzuschütteln.\n\nSpringen entfernt diese Kreaturen." }
