entries[311394] = { ["name"] = "Auslass", ["text"] = "Wirken in 2.5 sek. 5 sek. Abklingzeit\nEntfesselt eine Welle aus verderbtem Blut, die 7817 Schattenschaden verursacht und alle Gegner zurückstößt." }
