entries[311401] = { ["name"] = "Berührung des Verderbers", ["text"] = "100 Energie\nWirken in 3 sek. 3 sek. Abklingzeit\nIl'gynoth formt Spielercharaktere nach seinem Willen und verzaubert sie für 1 Min.. Während dieser Zeit versuchen Spielercharaktere unter seinem Einfluss, die 'Berührung des Verderbers' auf andere Spielercharaktere zu übertragen.\n\nDieser Effekt lässt sich entfernen, indem die Gesundheit betroffener Spielercharaktere auf unter 30% verringert wird." }
entries[311402] = { ["name"] = "Rasendes Blut", ["text"] = "Sofort\nDas Blut des Zaubernden fließt schneller. Der Rückstoßeffekt von ' Auslass ' erhöht sich mit jeder Anwendung." }
