entries[311408] = { ["name"] = "Kodex der jüngst Verschiedenen", ["text"] = "Wirken in 3 sek. 2\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeuchtende Tinte (10), Umbraltinte (10), Dunkles Pergament (50)\nOptionale Reagenzien:\nBeruf:\nInschriftenkunde der Schattenlande (20)\nLehrer:\nSchreiber Au'tehshi\nZone:\nOribos\nKosten:\n75\n\nKodex der jüngst Verschiedenen\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+20 Intelligenz\n+6 Ausdauer\n+ 4 Zufallswert 1\n+ 4 Zufallswert 2\n50" }
entries[311409] = { ["name"] = "Vertrag: Die Aufgestiegenen", ["text"] = "Wirken in 2 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeuchtende Tinte (5), Umbraltinte (5), Dunkles Pergament\nVerkäufer:\nAdjutantin Mikaros\nZone:\nOribos\nDie Aufgestiegenen - Respektvoll\nKosten:\n1.765\n\nVerkäufer:\nAdjutantin Nikos\nZone:\nBastion\nDie Aufgestiegenen - Respektvoll\nKosten:\n1.765\n\nBenutzen: Schließt einen Vertrag mit den Aufgestiegenen ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in den Schattenlanden abschließt.\n51\nBenötigt Die Aufgestiegenen\n- Freundlich" }
